import{_ as a,C as d,o as r,c as i,a2 as t,b as c,w as o,a as n,E as l,a7 as p}from"./chunks/framework.ClrTBeVd.js";const m=JSON.parse('{"title":"ui-forge 会话恢复与状态一致性","description":"","frontmatter":{"title":"ui-forge 会话恢复与状态一致性","outline":"deep","publish":true},"headers":[],"relativePath":"ai/ui-forge-session-recovery.md","filePath":"ai/ui-forge-session-recovery.md","lastUpdated":1790144657000}'),h={name:"ai/ui-forge-session-recovery.md"};function u(E,e,A,b,B,f){const s=d("Mermaid");return r(),i("div",null,[e[1]||(e[1]=t('<h1 id="ui-forge-会话恢复与状态一致性" tabindex="-1">ui-forge 会话恢复与状态一致性 <a class="header-anchor" href="#ui-forge-会话恢复与状态一致性" aria-label="Permalink to &quot;ui-forge 会话恢复与状态一致性&quot;">​</a></h1><p>ui-forge 支持在页面和 CLI 中操作同一个任务。这里要解决的是：用户关掉页面后，任务还能不能运行？服务重启后，历史从哪里找回来？两个入口同时操作，会不会重复执行？</p><h2 id="任务如何建立和保存" tabindex="-1">任务如何建立和保存 <a class="header-anchor" href="#任务如何建立和保存" aria-label="Permalink to &quot;任务如何建立和保存&quot;">​</a></h2><p>先区分两个概念：<code>thread</code> 是一整个会话，<code>turn</code> 是会话中的一轮执行。用户第一次提交需求会启动一轮，后续修改可以在同一个会话中继续。</p><p>本地服务（下文称 Server）准备好运行环境后，按顺序完成三件事：</p><ol><li>调用 <code>thread/start</code> 创建会话，把返回的 <code>thread.id</code> 作为 ui-forge 的 <code>taskId</code>。</li><li>保存任务索引，将这个 ID 与目标项目、设计绑定关联起来。</li><li>调用 <code>turn/start</code>，传入需求和图片，开始第一轮执行。</li></ol><p>会话创建后，Server 才会启动第一轮执行。如果这一步报错，已创建的任务仍会保留。用户可以打开原任务查看状态，再决定是否继续，不必重新创建任务。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionService.ts#L225" target="_blank" rel="noreferrer">源码：创建与首轮启动</a></p><p>创建任务后，数据分成三类：完整历史交给 Codex，导航和辅助信息由 ui-forge 落盘，当前连接的展示状态放在内存里。</p><table tabindex="0"><thead><tr><th>数据</th><th>保存位置</th><th>作用</th></tr></thead><tbody><tr><td>用户输入、模型回复、轮次和工具历史</td><td>Codex 原生会话存储</td><td>恢复对话和读取执行历史</td></tr><tr><td>任务 ID、项目目录、标题、更新时间、设计绑定</td><td><code>sessions.json</code></td><td>展示列表，定位原会话</td></tr><tr><td>规则指纹、运行配置、Agent 摘要、已观测的 Token</td><td><code>diagnostics/</code></td><td>排查问题，不驱动执行</td></tr><tr><td>用户上传的图片</td><td><code>attachments/</code></td><td>向 Codex 提供本地图片文件</td></tr><tr><td>展示缓存、已装载标记、待回复审批</td><td>Server 内存</td><td>支持当前连接和客户端重连</td></tr></tbody></table><p>ui-forge 的文件默认位于安装目录的 <code>.ui-forge/runtime/</code>，可通过 <code>UI_FORGE_RUNTIME_DIR</code> 修改。Codex 原生历史由它自己管理，项目通过接口读取，不直接解析底层文件。</p><p>其中，<code>sessions.json</code> 只是任务目录，不是聊天记录备份。只有索引、没有 Codex 原生历史，不能还原对话；索引丢失后，当前列表也不会自动导入其他 Codex 会话。</p><details class="details custom-block"><summary>同时保存多个任务，怎样避免记录丢失</summary><p><code>sessions.json</code> 保存的是完整任务列表。每次新增或更新任务，Server 都会生成一份新列表并整体替换文件，而不是在文件末尾追加一条记录。</p><p>例如，用户在页面创建任务 A，同时在 CLI 创建任务 B。如果两次更新都基于同一份旧列表，分别保存“旧列表 + A”和“旧列表 + B”，后一次保存就可能覆盖前一次，导致列表里少了一条任务记录。</p><p>Server 用两种方式保护这个文件：</p><ul><li><strong>排队保存，避免互相覆盖。</strong> A 保存成功后，B 再基于包含 A 的最新列表更新，因此两条记录都能保留。这里的排队只针对同一个 Server 内的索引更新，不是让任务轮流执行。</li><li><strong>先写临时文件，避免破坏原文件。</strong> 新列表完整写入临时文件后，再替换正式文件，成功后才更新内存中的列表。如果临时文件写入失败，原文件仍然保留。</li></ul><p>读取文件时，如果内容损坏或没有读取权限，Server 会明确报错，不会假装任务列表为空。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionIndex.ts#L13" target="_blank" rel="noreferrer">源码：SessionIndex</a></p></details><h2 id="断开后如何恢复" tabindex="-1">断开后如何恢复 <a class="header-anchor" href="#断开后如何恢复" aria-label="Permalink to &quot;断开后如何恢复&quot;">​</a></h2><p>页面和 CLI 只是操作入口，Codex 进程由 Server 托管。因此，关闭客户端和重启服务是两种不同的情况：</p><table tabindex="0"><thead><tr><th>断开的是什么</th><th>后台任务</th><th>重新打开时</th></tr></thead><tbody><tr><td>只关闭页面或 CLI</td><td>只要 Server 和对应 Codex 进程还在，就可以继续执行</td><td>复用连接和已装载的会话，发送当前快照，再接后续事件</td></tr><tr><td>Server 也退出了</td><td>它托管的 Codex 进程关闭，内存状态丢失</td><td>先读取索引恢复任务列表，打开某个任务时再准备连接，通过 <code>thread/resume</code> 加载历史</td></tr></tbody></table><p><code>thread/resume</code> 只是把已有会话装载到当前连接，<strong>不会重放旧输入，也不会自动启动新一轮</strong>。它不是让旧进程从中断位置继续跑。任务已经装载时则直接复用，不必再次调用。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionService.ts#L502" target="_blank" rel="noreferrer">源码：SessionService.load</a></p><h3 id="历史和实时消息怎么接起来" tabindex="-1">历史和实时消息怎么接起来 <a class="header-anchor" href="#历史和实时消息怎么接起来" aria-label="Permalink to &quot;历史和实时消息怎么接起来&quot;">​</a></h3><p>重连的客户端先拿到一份“快照”，也就是当前已有的消息和状态，再持续接收之后发生的“增量”。服务重启时，展示缓存先由 Codex 返回的历史重建。</p><p>这里不能先发快照、再开始监听，否则中间的新消息可能漏掉。Server 会先注册监听，再同步复制快照并开启事件队列：此前的事件归入快照，此后的事件进入队列，随后按顺序发送给客户端。消息按轮次 ID 归并，迟到的启动消息也不会把已结束的轮次改回运行中。</p><details class="details custom-block"><summary>快照读取与事件订阅的区别</summary><p>快照读取接口通过 <code>thread/read</code> 获取原生历史；事件订阅则发送 Server 的展示缓存快照和后续增量。展示缓存用于还原界面，不用于判断能否执行或审批是否有效。具体见 <a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionEventHub.ts" target="_blank" rel="noreferrer">SessionEventHub</a>。</p></details><h2 id="恢复后如何继续或停止" tabindex="-1">恢复后如何继续或停止 <a class="header-anchor" href="#恢复后如何继续或停止" aria-label="Permalink to &quot;恢复后如何继续或停止&quot;">​</a></h2><p>用户发送需求或点击“继续”时，Server 会先读取 Codex 的当前状态，再决定怎样处理：</p><table tabindex="0"><thead><tr><th>用户操作</th><th>当前有轮次在运行</th><th>当前没有轮次在运行</th></tr></thead><tbody><tr><td>发送普通消息，例如“把按钮改成蓝色”</td><td><code>turn/steer</code>，补进当前轮次</td><td><code>turn/start</code>，在原会话中启动新一轮</td></tr><tr><td>点击“继续任务”或执行 CLI 的 <code>resume</code></td><td>跳过，任务已经在运行</td><td><code>turn/start</code>，在原会话中启动新一轮</td></tr></tbody></table><p>用户不需要手动选择“补充”还是“新一轮”，两种调用都沿用原会话。手动发送“继续”两个字仍属于普通消息，不等同于“继续任务”操作。</p><p>因此，CLI 的 <code>ui-forge resume</code> 不只是原生 <code>thread/resume</code> 的同名包装：它连接原任务后，还会在空闲时发送继续请求。</p><p>停止操作通过 <code>turn/interrupt</code> 中断指定轮次。Server 会核对 <code>turnId</code>，防止旧页面误停后来开始的新轮次。RPC 超时不代表操作没有发生，后续操作仍需读取真实状态。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionService.ts#L291" target="_blank" rel="noreferrer">源码：读取、发送与停止</a></p><h2 id="多个入口如何协同" tabindex="-1">多个入口如何协同 <a class="header-anchor" href="#多个入口如何协同" aria-label="Permalink to &quot;多个入口如何协同&quot;">​</a></h2><p>页面和 CLI 不互相同步，而是共同操作 Server 中的同一个任务。下面以两端都打开任务 T、各发送一条普通消息为例：</p>',28)),(r(),c(p,null,{default:o(()=>[l(s,{id:"mermaid-264",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22sequence%22%3A%20%7B%22width%22%3A%20110%2C%20%22actorMargin%22%3A%2025%2C%20%22wrap%22%3A%20true%2C%20%22mirrorActors%22%3A%20false%7D%7D%7D%25%25%0AsequenceDiagram%0A%20%20participant%20page%20as%20%E9%A1%B5%E9%9D%A2%20A%0A%20%20participant%20cli%20as%20CLI%20B%0A%20%20participant%20server%20as%20Server%0A%20%20participant%20codex%20as%20Codex%20%E4%BC%9A%E8%AF%9D%20T%0A%20%20page-%3E%3Eserver%3A%20%E5%90%91%E4%BB%BB%E5%8A%A1%20T%20%E5%8F%91%E6%B6%88%E6%81%AF%0A%20%20server-%3E%3Ecodex%3A%20%E8%AF%BB%E5%8F%96%E5%BD%93%E5%89%8D%E7%8A%B6%E6%80%81%0A%20%20codex--%3E%3Eserver%3A%20%E5%BD%93%E5%89%8D%E7%A9%BA%E9%97%B2%0A%20%20server-%3E%3Ecodex%3A%20turn%2Fstart%0A%20%20cli-%3E%3Eserver%3A%20%E5%90%91%E4%BB%BB%E5%8A%A1%20T%20%E5%8F%91%E6%B6%88%E6%81%AF%0A%20%20server-%3E%3Ecodex%3A%20%E5%86%8D%E8%AF%BB%E5%BD%93%E5%89%8D%E7%8A%B6%E6%80%81%0A%20%20codex--%3E%3Eserver%3A%20%E4%BB%8D%E5%9C%A8%E8%BF%90%E8%A1%8C%0A%20%20server-%3E%3Ecodex%3A%20turn%2Fsteer%0A%20%20codex--%3E%3Eserver%3A%20%E4%BB%BB%E5%8A%A1%E4%BA%8B%E4%BB%B6%0A%20%20server--%3E%3Epage%3A%20%E6%9B%B4%E6%96%B0%E4%BB%BB%E5%8A%A1%E5%B1%95%E7%A4%BA%0A%20%20server--%3E%3Ecli%3A%20%E6%9B%B4%E6%96%B0%E4%BB%BB%E5%8A%A1%E5%B1%95%E7%A4%BA%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>图中 A 的消息先被处理，B 的消息到达时这轮还没结束，因此补进当前轮次。如果处理 B 时已经空闲，就按上一节的规则启动新一轮。任务事件会持续广播给两个已订阅的入口，不只在图末发送一次。</p><p>Server 按任务 ID 将发送和停止操作排队，每次处理前重新读取 Codex 状态，不直接相信某个入口显示的“空闲”。队列只等一次操作处理完，不等模型整轮执行结束，所以运行中仍能补充需求或停止。<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionService.ts#L307" target="_blank" rel="noreferrer">源码：send、stop 和 serial</a></p><p>两端同时打开任务时，Server 也会复用正在进行的连接初始化和会话加载，避免重复恢复。一端处理审批后，另一端会收到已处理事件，旧按钮不能重复提交；具体见<a href="/ai/ui-forge-process-approval">过程与审批</a>。</p><details class="details custom-block"><summary>如何避免重复恢复</summary><p>连接初始化和会话加载分别共用进行中的 Promise，后来的请求等待同一次操作。已经装载的会话直接复用，不再重复调用 <code>thread/resume</code>。</p></details><p>这里保证的是共用任务、按真实状态处理操作，再通过事件和重连快照更新展示，不是两个界面每一刻都完全相同。<strong>排队也不等于输入去重</strong>：两端发送相同文字仍是两次输入，这套机制只处理同一个 Server 内的并发。</p>',5))])}const v=a(h,[["render",u]]);export{m as __pageData,v as default};
